function validate([n, edges, disappear]) {
  if (!Number.isInteger(n) || n < 1 || n > 50000) return 'n is between 1 and 50000.';
  if (edges.length > 100000) return 'There are at most 100000 edges.';
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is [u, v, length].';
    const [u, v, length] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge endpoints are between 0 and n - 1.';
    if (!Number.isInteger(length) || length < 1 || length > 100000) return 'Each length is between 1 and 100000.';
  }
  if (disappear.length !== n) return 'disappear has exactly n values.';
  if (disappear.some(t => !Number.isInteger(t) || t < 1 || t > 100000)) return 'Each disappear time is between 1 and 100000.';
  return null;
}

