function minimumTime(n, edges, disappear) {
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v, length] of edges) {
    graph[u].push([v, length]);
    graph[v].push([u, length]);
  }
  const answer = new Array(n).fill(-1);
  const heap = [[0, 0]];
  const push = (entry) => {
    heap.push(entry);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === i) break;
        [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
        i = smallest;
      }
    }
    return top;
  };
  while (heap.length > 0) {
    const [time, node] = pop();
    if (answer[node] !== -1) continue;
    answer[node] = time;
    for (const [next, length] of graph[node]) {
      const arrival = time + length;
      if (answer[next] === -1 && arrival < disappear[next]) {
        push([arrival, next]);
      }
    }
  }
  return answer;
}

