function minimumTime(n, edges, disappear) {
  // Bellman-Ford style relaxation: keep improving arrival times until nothing changes.
  const best = new Array(n).fill(Infinity);
  best[0] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b, w] of edges) {
      for (const [from, to] of [[a, b], [b, a]]) {
        const t = best[from] + w;
        if (t < disappear[to] && t < best[to]) { best[to] = t; changed = true; }
      }
    }
  }
  return best.map(t => (t === Infinity ? -1 : t));
}

