function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 6);
    const m = pick(0, 9);
    const edges = [];
    for (let i = 0; i < m; i++) edges.push([pick(0, n - 1), pick(0, n - 1), pick(1, 6)]);
    const disappear = Array.from({ length: n }, () => pick(1, 14));
    return [n, edges, disappear];
  }
  const n = pick(1000, 2000);
  const edges = [];
  // A random tree keeps most nodes connected, then extra edges add alternative routes.
  for (let i = 1; i < n; i++) edges.push([pick(0, i - 1), i, pick(1, 3000)]);
  while (edges.length < 2000) edges.push([pick(0, n - 1), pick(0, n - 1), pick(1, rand() < 0.1 ? 100000 : 3000)]);
  const disappear = Array.from({ length: n }, () => pick(1, 100000));
  return [n, edges, disappear];
}
